# -*- coding=utf-8 -*-

import re

# -------------------
# فئة استثناء خاصة
class MyError(Exception):
    pass

class Personne:

    # منشئ
    def __init__(self,prenom="x",nom="x",age=0):
         # يجب ألا يكون الاسم الأول فارغًا
        match=re.match(r"^\s*(\S+)\s*$",prenom)
        if not match:
            raise MyError("Le prenom ne peut etre vide")
        else:
            self.prenom=match.groups()[0]
        # يجب ألا يكون الاسم فارغًا
        match=re.match(r"^\s*(\S+)\s*$",nom)
        if not match:
            raise MyError("Le nom ne peut etre vide")
        else:
            self.nom=match.groups()[0]
        # يجب أن يكون العمر صالحًا
        match=re.match(r"^\s*(\d+)\s*$",str(age))
        if not match:
            raise MyError("l'age doit etre un entier positif")
        else:
            self.age=match.groups()[0]

    def __str__(self):
        return "[{0},{1},{2}]".format(self.prenom,self.nom,self.age)

# ---------------------------------- اليد
# كائن «شخص»
try:
    p=Personne("  Paul  ","  Langevin  ",48)
    print "personne={0}".format(p)
except MyError, erreur:
    print erreur
# كائن «شخص» آخر
try:
    p=Personne("  xx  ","  yy  ","  zz")
    print "personne={0}".format(p)
except MyError, erreur:
    print erreur
# شخص آخر
try:
    p=Personne()
    print "personne={0}".format(p)
except MyError, erreur:
    print erreur
</code></pre> <p>ملاحظات:</p> <ul> <li>السطران 7-8: فئة MyError مشتقة من الفئة Exception. وهي لا تضيف أي وظائف إلى هذه الأخيرة. إن وجودها يقتصر على توفير استثناء خاص بها؛</li> <li>السطر 13: يحتوي المنشئ على قيم افتراضية لمعلماته. وبالتالي، فإن العملية p=Personne() تعادل p=Personne("x","x",0)؛</li> <li>الأسطر 15-9: يتم تحليل المعلمة prenom. يجب ألا تكون فارغة. إذا لم يكن الأمر كذلك، يتم إثارة الاستثناء MyError مع رسالة خطأ؛</li> <li>الأسطر 21-25: الأمر نفسه بالنسبة للاسم؛</li> <li>الأسطر 27-31: التحقق من العمر؛</li> <li>السطران 33-34: تحل الدالة __str__ محل الطريقة التي كانت تُسمى سابقًا identite؛</li> <li>الأسطر 38-42: إنشاء مثيل لشخص ثم عرض هويته؛</li> <li>السطر 39: إنشاء مثيل؛</li> <li>السطر 40: العرض. تطلب العملية عرض الشخص p في شكل سلسلة أحرف. ثم يقوم مترجم Python تلقائيًا باستدعاء الطريقة p.__str__() إن وجدت. تؤدي هذه الطريقة نفس دور الطريقة toString() في لغة Java أو في لغات .NET؛</li> <li>السطور 41-42: معالجة أي استثناء محتمل من النوع MyError. ثم يعرض رسالة الخطأ المرتبطة بالاستثناء؛</li> <li>الأسطر 44-48: الأمر نفسه بالنسبة لشخص ثانٍ تم إنشاء مثيل له باستخدام معلمات خاطئة؛</li> <li>الأسطر 50-54: الأمر نفسه بالنسبة لشخص ثالث تم إنشاء مثيل له باستخدام المعلمات الافتراضية.</li> </ul> النتائج <pre><code>personne=[Paul,Langevin,48]
l'age doit etre un entier positif
personne=[x,x,0]
</code></pre> <p></p>

البرنامج (classes_05) <pre><code>
# -*- coding=utf-8 -*-

import re

# -------------------
# فئة استثناء مالكة
class MyError(Exception):
    pass

class Personne:
    # سمات الفئة
    # غير مُعلنة - يمكن إنشاؤها ديناميكيًا

    # منشئ
    def __init__(self,prenom="x",nom="x",age=0):
         # يجب ألا يكون حقل الاسم فارغًا
        match=re.match(r"^\s*(\S+)\s*$",prenom)
        if not match:
            raise MyError("Le prenom ne peut etre vide")
        else:
            self.prenom=match.groups()[0]
        # يجب ألا يكون اسم العائلة فارغًا
        match=re.match(r"^\s*(\S+)\s*$",nom)
        if not match:
            raise MyError("Le nom ne peut etre vide")
        else:
            self.nom=match.groups()[0]
            # يجب أن يكون العمر صالحًا
        match=re.match(r"^\s*(\d+)\s*$",str(age))
        if not match:
            raise MyError("l'age doit etre un entier positif")
        else:
            self.age=match.groups()[0]

    def initWithPersonne(self,p):
        # تقوم بتهيئة الكائن الحالي بشخص p
        self.__init__(p.prenom,p.nom,p.age)

    def __str__(self):
        return "[{0},{1},{2}]".format(self.prenom,self.nom,self.age)

# ---------------------------------- main
# كائن «شخص»
try:
    p0=Personne("  Paul  ","  Langevin  ",48)
    print "personne={0}".format(p0)
except MyError, erreur:
    print erreur
# كائن «شخص» آخر
try:
    p1=Personne("  xx  ","  yy  ","  zz")
    print "personne={0}".format(p1)
except MyError, erreur:
    print erreur
# شخص آخر
p2=Personne()
try:
    p2.initWithPersonne(p0)
    print "personne={0}".format(p2)
except MyError, erreur:
    print erreur

</code></pre> <p>ملاحظات:</p> <ul> <li>يكمن الاختلاف عن البرنامج النصي السابق في الأسطر 35-37. تمت إضافة الطريقة initWithPersonne. وتستدعي هذه الطريقة المنشئ __init__. لا توجد إمكانية، كما هو الحال في اللغات المحددة الأنواع، لوجود طرق تحمل الاسم نفسه وتتميز بطبيعة معلماتها أو نتائجها. وبالتالي، لا توجد إمكانية لوجود عدة منشئات تقوم بإنشاء الكائن بناءً على معلمات مختلفة، وهنا كائن من النوع Personne.</li> </ul> النتائج <pre><code>personne=[Paul,Langevin,48]
l'age doit etre un entier positif
personne=[Paul,Langevin,48]
</code></pre> <p></p>

